#!/usr/bin/env bash
# Builds the workspace before the agent starts. claude plugin eval runs it
# only under --scaffold, with the empty workspace as the working directory.
set -euo pipefail
mkdir -p scripts
printf '%s' '' | base64 -d > client.py
printf '%s' '' | base64 -d > test_client.py
printf '%s' '' | base64 -d > scripts/fixture_server.py
git init -q 2>/dev/null || true
git add -A 2>/dev/null || true
git -c user.email=e@e -c user.name=e commit -qm 'baseline: sync client and fixture server' 2>/dev/null || true
